dtsPropsFor.Button:
/** "primary" = filled accent call-to-action (one per screen), "default" = bordered card-colored button, "danger" = filled red destructive action, "quiet" = borderless accent text button (add className "neg" for red text). */
  variant?: "default" | "primary" | "danger" | "quiet";
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  disabled?: boolean;
  /** Spinner over the hidden (still sized) label, disabled + aria-busy: no width jump while submitting. */
  loading?: boolean;
  type?: "button" | "submit" | "reset";
  className?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;
  /** Any other native <button> attribute is forwarded. */
  [attr: string]: unknown;

dtsPropsFor.Card:
/** Dimmed (opacity 0.5), e.g. a paused habit. */
  inactive?: boolean;
  /** Layout utility from the global stylesheet, e.g. "stack-sm" (vertical) or "row" (space-between). */
  className?: string;
  onClick?: (event: React.MouseEvent<HTMLDivElement>) => void;
  style?: React.CSSProperties;
  children?: React.ReactNode;
  /** Any other native <div> attribute is forwarded. */
  [attr: string]: unknown;

dtsPropsFor.SegmentedControl:
/** Equal-width buttons, left to right. tone colors the selected segment (pos = green, neg = red), accent when omitted. bars (1-3) shows importance bars before the label (rest dimmed). */
  options: { value: string; label: string; tone?: "pos" | "neg"; bars?: 1 | 2 | 3 }[];
  /** Selected option value. Nothing is selected when undefined. */
  value?: string;
  onChange: (value: string) => void;

dtsPropsFor.TabBar:
/** Tabs. badge shows a red attention dot after the label. */
  items: { id: string; label: string; badge?: boolean }[];
  /** id of the selected tab (accent color, bold). */
  active: string;
  onSelect: (id: string) => void;

dtsPropsFor.HistoryEntry:
/** One reviewed day from the rating ledger: day is "YYYY-MM-DD", delta is the signed day total, contributions explain it line by line (rendered when the entry is expanded). */
  entry: {
    day: string; rulesetVersion: string; reviewRevision: number;
    status: "reviewed" | "unknown"; ratingBefore: number; delta: number; ratingAfter: number;
    dayScore: number; expected: number; clamped: boolean;
    contributions: {
      source: { kind: "habit"; habitId: string } | { kind: "clean_day" } | { kind: "streak_bonus"; habitId: string } | { kind: "unknown_day" };
      zone?: "excellent" | "ok" | "tolerable" | "bad" | "unknown" | "not_applicable";
      points: number; multiplier: number;
    }[];
  };
  /** habitId -> name and the direction/tier in effect on the entry's day, used to group habit lines. */
  habits: Map<string, { name: string; direction: 'constructive' | 'destructive'; tier: 'weak' | 'medium' | 'strong' }>;
  /** Starts expanded (still collapsible). Remount with a new key to re-apply. */
  defaultOpen?: boolean;

dtsPropsFor.Field:
/** Label text above the control. */
  label: string;
  /** Shows a red asterisk after the label. */
  required?: boolean;
  /** Short muted text inside the left edge of the control, e.g. "@". */
  prefix?: string;
  /** Muted helper text under the control; hidden while error is shown. */
  hint?: string;
  /** Red error text under the control. The input gets aria-invalid automatically. */
  error?: string;
  /** Node inside the control's right edge (e.g. a show/hide button); adds right padding to the input. */
  trailing?: React.ReactNode;
  className?: string;
  /** A single native control, e.g. <input>. */
  children: React.ReactNode;

dtsPropsFor.Avatar:
/** Photo URL or data URL. Initials of name are shown when absent. */
  src?: string;
  /** Used for the initials fallback. */
  name: string;
  /** Diameter in px (default 96). */
  size?: number;
  /** Makes the avatar a button (edit mode) with a dashed border. */
  onClick?: () => void;
  /** Accessible name of the button, e.g. "Выбрать фото". Only used with onClick. */
  label?: string;
  /** Disables the button. Only used with onClick. */
  disabled?: boolean;
  className?: string;

dtsPropsFor.Dialog:
/** Renders nothing when false. */
  open: boolean;
  /** Bold heading; also the accessible name (aria-labelledby). */
  title: string;
  /** Called on Escape and on overlay click. */
  onClose: () => void;
  /** Body text (<p className="dialog-body">) and actions (<div className="dialog-actions"> with full-width Buttons; put autoFocus on the safe one). */
  children: React.ReactNode;

dtsPropsFor.BottomSheet:
/** Renders nothing when false. */
  open: boolean;
  /** Heading in the sheet header; also the accessible name (aria-labelledby). */
  title: string;
  /** Called on Escape, overlay click and the close button. */
  onClose: () => void;
  /** Accessible name of the round close button (the component has no built-in language). */
  closeLabel: string;
  /** Sticky footer under the scrollable body (e.g. the primary action); hidden when omitted. */
  footer?: React.ReactNode;
  /** Scrollable sheet body: a form, or a pick list <div className="sheet-options"> of <button className="sheet-option" aria-pressed={selected}> rows with a trailing <span className="sheet-check">✓</span> on the selected one. */
  children: React.ReactNode;

dtsPropsFor.Notice:
/** success = green, role=status; error = red, role=alert. */
  tone: "success" | "error";
  children: React.ReactNode;

dtsPropsFor.PasswordField:
/** Label shown above the input and associated with it. */
  label: string;
  /** Controlled: true shows the password as plain text, false masks it. */
  visible: boolean;
  onToggleVisible: () => void;
  /** Strength meter level (0 = hidden). Shown only when > 0 and there is no error. */
  strength?: 0 | 1 | 2 | 3;
  /** Toggle button texts (the component has no built-in language). */
  showLabel: string;
  hideLabel: string;
  /** Meter texts for strength 1..3: [weak, fair, strong]. */
  strengthLabels?: readonly [string, string, string];
  /** Error text below the input (--neg); sets aria-invalid and hides the meter. */
  error?: string;
  className?: string;
  /** Any other native <input> attribute (value, onChange, autoComplete...) is forwarded; type is managed by `visible`. */
  [attr: string]: unknown;

dtsPropsFor.FullScreenModal:
/** Accessible name of the dialog (aria-label). */
  label: string;
  /** Modal content. Full-screen, non-closable (no Esc, no backdrop, no close button); focus is trapped and returns to the opener on unmount. The caller unmounts it. */
  children: React.ReactNode;

dtsPropsFor.ProgressSegments:
/** Number of cards (one segment each). */
  total: number;
  /** Zero-based index of the current card: earlier segments are done, later ones pending. */
  current: number;
  /** Counter text shown above the segments, e.g. "2 из 5" (the component has no built-in language). */
  counterLabel: string;
  className?: string;

dtsPropsFor.QuotaDots:
/** Occurrences already used this week. */
  used: number;
  /** Effective weekly limit (one dot each). Warn tone, neg when used >= limit. */
  limit: number;
  /** Note under the dots, e.g. "Использовано 2 из 3" (the component has no built-in language). */
  note: string;
  className?: string;

dtsPropsFor.SwipeCard:
/** Small uppercase caption on the card, e.g. "Привычка". */
  typeLabel: string;
  /** Big card title (habit name). */
  title: string;
  /** Question under the title, e.g. "Сделали вчера?". */
  question: string;
  /** Right / ✓ answer text (the component has no built-in language). */
  goodLabel: string;
  /** Left / ✕ answer text. */
  badLabel: string;
  /** Muted line at the card bottom, e.g. "Свайп вправо — сделал, влево — не сделал". */
  hint: string;
  /** Text of the quiet "not applicable" button; hidden when omitted. */
  notApplicableLabel?: string;
  /** Called once per card after the swipe/button/ArrowLeft/ArrowRight answer. Remount with a new key per card. */
  onAnswer: (answer: "good" | "bad" | "not_applicable") => void;
  /** Extra card content under the title (e.g. a QuotaDots block). */
  children?: React.ReactNode;
  /** Shows a card-shaped peek behind (a next card exists). */
  peek?: boolean;

dtsPropsFor.Stepper:
/** Current value, clamped to min..max by the buttons. */
  value: number;
  min: number;
  max: number;
  onChange: (value: number) => void;
  /** Accessible names of the − and + buttons (the component has no built-in language). */
  decLabel: string;
  incLabel: string;
  /** Muted text left of the controls, e.g. "Дней в неделю". */
  label?: string;
  className?: string;

dtsPropsFor.WeekDots:
/** Days counted this week, 0-7 (7 bars Mon-Sun, display only). */
  value: number;
  /** constructive: first `value` green, rest dim. destructive: first `value` muted (allowed), rest red-tinted. */
  direction: "constructive" | "destructive";
  className?: string;

dtsPropsFor.ChipGroup:
/** Single-select pill chips, wrapping. tone is ignored. */
  options: { value: string; label: string }[];
  /** Selected option value. */
  value?: string;
  onChange: (value: string) => void;
  /** Accessible name of the radio group. */
  label: string;
  className?: string;

dtsPropsFor.TypeCards:
/** Two selectable cards with a +/− circle. tone pos = green, neg = red (selected state is tinted). */
  options: { value: string; title: string; description: string; tone: "pos" | "neg" }[];
  /** Selected option value. */
  value?: string;
  onChange: (value: string) => void;
  /** Accessible name of the radio group. */
  label: string;
  /** Locks the choice (selected card stays highlighted, the other is dimmed). */
  disabled?: boolean;
  className?: string;

dtsPropsFor.Select:
/** Custom dropdown: field-like trigger with a chevron; the option list floats over the page (fixed, flips above near the bottom) with a ✓ on the selected row. */
  options: { value: string; label: string }[];
  /** Selected option value; placeholder is shown when nothing matches. */
  value?: string;
  onChange: (value: string) => void;
  /** Accessible name of the trigger and the list. */
  label: string;
  placeholder?: string;
  disabled?: boolean;
  className?: string;

dtsPropsFor.Spinner:
/** Diameter in px (default 18). Spinning ring in currentColor. */
  size?: number;
  /** Accessible text (role=status); decorative when omitted. */
  label?: string;
  className?: string;

dtsPropsFor.StatTile:
/** Read-only summary tile: colored dot + title + total, then one row per tier (importance bars, label, count; zero counts dimmed). */
  title: string;
  /** Big number at the top right. */
  total: number;
  /** Dot color: pos = green, neg = red. */
  tone: "pos" | "neg";
  /** Rows top to bottom; level (1-3) sets the filled bars. */
  rows: { label: string; value: number; level: 1 | 2 | 3 }[];
  className?: string;

dtsPropsFor.Menu:
/** ⋮ button (44x44) with a small popover menu: opens under the trigger, flips above near the bottom; closes on outside tap, Esc, second tap and after a pick. */
  items: { id: string; label: string; tone?: "danger"; separatorBefore?: boolean }[];
  /** Called with the picked item id. */
  onSelect: (id: string) => void;
  /** Accessible name of the ⋮ trigger. */
  triggerLabel: string;
  className?: string;

dtsPropsFor.Skeleton:
/** Shimmering placeholder block while data loads (aria-hidden). CSS width, default 100%. */
  width?: number | string;
  /** CSS height, default 1em. */
  height?: number | string;
  /** Border radius in px, or "full" for circles/pills; default --radius-sm. */
  radius?: number | "full";
  className?: string;
  style?: React.CSSProperties;
